/// Creates the Snowball stemmer of a language by its Lucene class prefix ("English").
pub fn new_stemmer(lang: &str) -> Option<Box<dyn super::snowball::Stemmer + Send>> {
    match lang {
        "Arabic" => Some(Box::new(arabic::ArabicStemmer::default())),
        "Armenian" => Some(Box::new(armenian::ArmenianStemmer::default())),
        "Basque" => Some(Box::new(basque::BasqueStemmer::default())),
        "Catalan" => Some(Box::new(catalan::CatalanStemmer::default())),
        "Danish" => Some(Box::new(danish::DanishStemmer::default())),
        "Dutch" => Some(Box::new(dutch::DutchStemmer::default())),
        "English" => Some(Box::new(english::EnglishStemmer::default())),
        "Estonian" => Some(Box::new(estonian::EstonianStemmer::default())),
        "Finnish" => Some(Box::new(finnish::FinnishStemmer::default())),
        "French" => Some(Box::new(french::FrenchStemmer::default())),
        "German" => Some(Box::new(german::GermanStemmer::default())),
        "Greek" => Some(Box::new(greek::GreekStemmer::default())),
        "Hindi" => Some(Box::new(hindi::HindiStemmer::default())),
        "Hungarian" => Some(Box::new(hungarian::HungarianStemmer::default())),
        "Indonesian" => Some(Box::new(indonesian::IndonesianStemmer::default())),
        "Irish" => Some(Box::new(irish::IrishStemmer::default())),
        "Italian" => Some(Box::new(italian::ItalianStemmer::default())),
        "Lithuanian" => Some(Box::new(lithuanian::LithuanianStemmer::default())),
        "Nepali" => Some(Box::new(nepali::NepaliStemmer::default())),
        "Norwegian" => Some(Box::new(norwegian::NorwegianStemmer::default())),
        "Porter" => Some(Box::new(porter::PorterStemmer::default())),
        "Portuguese" => Some(Box::new(portuguese::PortugueseStemmer::default())),
        "Romanian" => Some(Box::new(romanian::RomanianStemmer::default())),
        "Russian" => Some(Box::new(russian::RussianStemmer::default())),
        "Serbian" => Some(Box::new(serbian::SerbianStemmer::default())),
        "Spanish" => Some(Box::new(spanish::SpanishStemmer::default())),
        "Swedish" => Some(Box::new(swedish::SwedishStemmer::default())),
        "Tamil" => Some(Box::new(tamil::TamilStemmer::default())),
        "Turkish" => Some(Box::new(turkish::TurkishStemmer::default())),
        "Yiddish" => Some(Box::new(yiddish::YiddishStemmer::default())),
        _ => None,
    }
}
